    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "ts-route-plan-service calls to ts-travel2-service: 21 of 400 failed with 500."}]},
